import{apiClient}from"./client";const getCars=async a=>{return(await apiClient.get("/carList?organizationSlug=hyundai-cn",{params:a?{organizationSlug:a}:{}})).data.items},getCarByVin=async(a,t)=>{return(await apiClient.get(`/carList/${a}?organizationSlug=hyundai-cn`,{params:{organizationSlug:t}})).data};export{getCars,getCarByVin};